<script setup lang="ts">const api=useRuntimeConfig().public.apiBase; const email=ref(''); const password=ref(''); async function submit(){await $fetch(`${api}/auth/register`,{method:'POST',body:{email:email.value,password:password.value}}); navigateTo('/login')}</script>
<template><main class="min-h-screen grid place-items-center"><form class="bg-blue-900 p-8 rounded-xl grid gap-4 w-80" @submit.prevent="submit"><h1 class="text-2xl">Registro</h1><input v-model="email" type="email" placeholder="Correo" class="p-2 text-black"><input v-model="password" type="password" placeholder="Contraseña (8+)" class="p-2 text-black"><button class="bg-cyan-400 text-black p-2 rounded">Registrarme</button><NuxtLink to="/login">Ya tengo cuenta</NuxtLink></form></main></template>
